ProcessResult run(List<String> argv,Map<String,String> env,String label,{int maximum=180,bool mustPass=true,bool cleanup=false}){final remaining=cleanup?maximum:1800-wall.elapsed.inSeconds-60;require(remaining>0,'30minute cap');final seconds=remaining<maximum?remaining:maximum;final command=['--kill-after=10s','$seconds',...argv];final r=Process.runSync('/usr/bin/timeout',command,environment:env,includeParentEnvironment:false);final stem='$raw/commands/${(counter++).toString().padLeft(5,'0')}-$label';File(stem).parent.createSync(recursive:true);File('$stem.stdout').writeAsStringSync(r.stdout as String);File('$stem.stderr').writeAsStringSync(r.stderr as String);save('$stem.json',{'argv':['/usr/bin/timeout',...command],'exit_code':r.exitCode,'timed_out':r.exitCode==124||r.exitCode==137});if(mustPass)require(r.exitCode==0,'Command failed: $label, retainedlogs');return r;}
int diskBytes(String path){final d=Directory(path);if(!d.existsSync())return 0;var n=0;for(final f in d.listSync(recursive:true,followLinks:false)){if(f is File)n+=f.lengthSync();}return n;}
void budget(int next){final roots=[owned,'/home/bsutton/.cache/rv-streamreserve-20261012','$worktree/rust/target/object-stream-reserve-20261012/bin','$worktree/rust/target/direct-page-body-20261012/bin','/home/bsutton/.cache/rv-memdiag-20261012','$worktree/rust/target/import-memory-attribution-20261012/bin','/home/bsutton/.cache/rv-zipcmp-20261012','/home/bsutton/.cache/rv-protzip-20261012','/home/bsutton/.cache/rv-pagelife-20261012','$worktree/rust/target/public-zip-comparison-20261012/bin','/home/bsutton/.cache/rv-pagebody-20261012','$worktree/rust/target/page-body-borrow-20261012/bin','/home/bsutton/.cache/rv-pageown-20261012','$worktree/rust/target/page-flush-ownership-20261012/bin','/home/bsutton/.cache/rv-addcache8-20261012','$worktree/rust/target/single-file-add-cache8-20261012/bin','/home/bsutton/.cache/rv-rawown-20261012','$worktree/rust/target/raw-frame-ownership-20261012/bin','/home/bsutton/.cache/rv-addcache-20261012','$worktree/rust/target/single-file-add-cache-20261012/bin','/home/bsutton/.cache/rv-win-20261012','$worktree/rust/target/import-window-20261012/bin','/home/bsutton/.cache/rv-enc-20261012','$worktree/rust/target/page-body-lifetime-20261012/bin','/home/bsutton/.cache/rv-add1-20261012','$worktree/rust/target/parallel-encoder-reuse-202612/bin','/home/bsutton/.cache/rv-add-20261012','/home/bsutton/.cache/rv-single-20261012','$worktree/rust/target/explicit-file-extraction-20261012/bin','/home/bsutton/.cache/rv-many-20261012','/home/bsutton/.cache/rv-many-zstd-20261012','/home/bsutton/.cache/revault-native-public-20261011','/home/bsutton/.cache/rv-credential-20261012','$worktree/rust/target/credential-open-20261012/bin','$worktree/rust/target/parallel-extraction-202612/bin','$worktree/rust/target/native-public-20261011/bin','$worktree/rust/target/native-extract-cache-budget-20261011/bin',evidence];final total=roots.map(diskBytes).fold<int>(0,(a,b)=>a+b);require(total+next<=24*1024*1024*1024,'24GiB ownedcap');final r=Process.runSync('/usr/bin/df',['-Pk',owned]);require(r.exitCode==0,'df');final fields=(r.stdout as String).trim().split('\n').last.split(RegExp(r'\s+'));require(int.parse(fields[3])*1024>=next+2*1024*1024*1024,'headroom');}
void agent(int c,{required bool start}){final e=environment(c);final socket='${e['LOCKBOX_SESSION_AGENT_DIR']}/agent.sock';if(start){final r=run([cli,'session','--format','json'],e,'session$c',maximum:20);final rows=(r.stdout as String).split('\n').where((v)=>v.trim().isNotEmpty).map(jsonDecode);require(rows.any((v)=>v is Map&&v['kind']=='agent'&&v['state']=='running'&&v['value']=='yes'),'agent roundtrip');run(['/usr/bin/test','-S',socket],e,'socket$c',maximum:5);}else{final present=run(['/usr/bin/test','-S',socket],e,'cleanup-present$c',maximum:5,mustPass:false,cleanup:true);if(present.exitCode==1)return;require(present.exitCode==0,'Socket inspection failed');run([cli,'session','stop'],e,'stop$c',maximum:20,cleanup:true);run(['/usr/bin/test','!','-S',socket],e,'stopped$c',maximum:5,cleanup:true);}}
void cleanupAgents(List<int> cases){final results=<Map<String,dynamic>>[];for(final c in cases){try{agent(c,start:false);results.add({'case':c,'stopped':true});}catch(error){results.add({'case':c,'stopped':false,'error':'$error'});}}save('$raw/cleanup-${DateTime.now().microsecondsSinceEpoch}.json',{'rows':results,'passed':results.every((r)=>r['stopped']==true)});require(results.every((r)=>r['stopped']==true),'Owned cleanup incomplete');}
List<Map<String,dynamic>> cases()=>(jsonDecode(File('$raw/cases.json').readAsStringSync()) as List).cast<Map<String,dynamic>>();
void identities(){for(final e in (object('$raw/baseline-identities.json')['hashes'] as Map).entries)require(sha(e.key)==e.value,'Changed identity');}
void cold(String archive,Map<String,String> env,String id){for(var a=0;a<3;a++){run(['/usr/bin/sync','-d','--',archive],env,'$id-sync$a',maximum:30);run(['/usr/bin/fadvise','--advice','dontneed',archive],env,'$id-evict$a',maximum:30);final r=run(['/usr/bin/fincore','--json','--bytes','--output','RES,FILE',archive],env,'$id-res$a',maximum:30);final rows=jsonDecode(r.stdout)['fincore'] as List;if(int.parse('${rows.single['res']}')==0)return;}throw StateError('Cold gate failed');}
void verifyOutput(Map<String,dynamic> spec,String output,Map<String,String> env,String id){
 require(FileSystemEntity.typeSync(output,followLinks:false)==FileSystemEntityType.file,'Regular output');final f=File(output);require(f.lengthSync()==spec['bytes']&&(f.statSync().mode&0x1ff)==0x180,'Output size/stored mode0600');run(['/usr/bin/cmp','-s','--',spec['source'] as String,output],env,'$id-compare');run(['/usr/bin/sync','-d','--',output,f.parent.path],env,'$id-output-drain',maximum:60);
}
List<String> addArgs(Map<String,dynamic> spec,String archive,int workflow,{String executable=cli}){final source=spec['source'] as String;return workflow==0?[executable,archive,'add',source,'--to','/payload.bin']:[executable,archive,'add','--recursive',File(source).parent.path,'--include',source.split('/').last,'--to','/data'];}
void create(String archive,Map<String,String> env,String id){require(!File(archive).existsSync(),'Fresh archive');run([cli,archive,'create','--encryption','none','--signing','none','--compression','zstd','--compression-level','3'],env,'$id-create');}
String verifyArchive(Map<String,dynamic> spec,String archive,int workflow,Map<String,String> env,String id){
 final inspect=run([cli,archive,'doctor'],env,'$id-doctor',maximum:600).stdout as String;
 for(final field in ['encryption: none','signing: none','compression: zstd (level 3)','size padding: default'])require(inspect.contains(field),'Public format mismatch');
 final listing=run([cli,archive,'list','--recursive','--format','json'],env,'$id-list').stdout as String;
 final rows=listing.split('\n').where((v)=>v.trim().isNotEmpty).map(jsonDecode).toList();final files=rows.where((v)=>v['kind']=='file').toList();require(files.length==1&&int.parse('${files.single['len']}')==spec['bytes'],'Sole payload');require(rows.every((v)=>v['kind']=='file'||v['kind']=='directory'),'Unexpected entry kind');final path=files.single['path'] as String;final expected=workflow==0?'/payload.bin':'/data/${(spec['source'] as String).split('/').last}';require(path==expected,'Exact selected public path');return path;
}
void setup(){require(!File('$raw/cases.json').existsSync(),'Existing diagnostic setup');Directory(owned).createSync(recursive:true);require(sha(cli)==expectedCli,'Pinned binary');const previous='$worktree/docs/evidence/public-add-2026-10-12/raw';final complete=object('$previous/baseline-complete.json');require(complete['accepted']==16&&complete['identities_verified_after']==true&&complete['owned_agents_stopped']==true,'Original baseline incomplete');final inputs=(jsonDecode(File('$previous/cases.json').readAsStringSync()) as List).cast<Map<String,dynamic>>();require(inputs.length==2,'Two inputs');final records=<Map<String,dynamic>>[];for(var c=0;c<2;c++){final spec=Map<String,dynamic>.from(inputs[c]);require(sha(spec['source'])==spec['source_sha256']&&File(spec['source']).lengthSync()==spec['bytes'],'Source identity');final siblings=File(spec['source']).parent.listSync(followLinks:false).toList();require(siblings.length==1&&siblings.single.path==spec['source']&&siblings.single is File,'One-file source directory');final root='$owned/fixture$c';require(!Directory(root).existsSync(),'Existing partial fixture');Directory(root).createSync(recursive:true);spec['root']=root;records.add(spec);}save('$raw/cases.json',records);}
void freeze(){require(!File('$raw/paired-identities.json').existsSync(),'Already frozen');require(sha(cli)==expectedCli&&sha(trialCli)==expectedTrial,'Binary identities');final hashes=<String,String>{};final manifest='$raw/build-new/manifest.txt';final build=File(manifest).readAsStringSync();require(build.contains(expectedTrial),'Build artifact');for(final relative in ['revault_lockbox_api/src/file_format/page.rs','revault_lockbox_api/src/lockbox/files.rs','revault_lockbox_api/src/model/page_object_packer.rs','Cargo.toml','Cargo.lock','revault_lockbox_api/src/compression.rs','revault_lockbox_api/src/compression/encode_workspace.rs','revault_lockbox_api/src/lockbox/file_import_pipeline.rs','revault_cli/src/commands/files.rs','revault_lockbox_api/src/lockbox.rs','revault_lockbox_api/src/storage/page_cache.rs','revault_lockbox_api/Cargo.toml','revault_cli/Cargo.toml']){final p='$worktree/rust/$relative';final digest=sha(p);require(build.contains('$digest  $relative'),'Build/source mismatch');hashes[p]=digest;}for(final p in ['/usr/bin/time','/usr/bin/taskset','/usr/bin/sync','/usr/bin/timeout','/usr/bin/fadvise','/usr/bin/fincore','/usr/bin/cmp',cli,trialCli,Platform.script.toFilePath(),'$evidence/README.md','$raw/cases.json',manifest,'$worktree/docs/evidence/public-zip-comparison-2026-10-12/raw/build-current/binary-sha256.txt','$worktree/tools/summarize-direct-page-body.dart','$worktree/tools/summarize-adaptive-workers.dart','$worktree/docs/evidence/public-add-2026-10-12/raw/baseline-identities.json','$worktree/docs/evidence/public-add-2026-10-12/raw/baseline-complete.json','$worktree/docs/evidence/public-add-serial-2026-10-12/raw/baseline-identities.json','$worktree/docs/evidence/public-add-serial-2026-10-12/raw/baseline-complete.json'])hashes[p]=sha(p);for(final spec in cases()){require(sha(spec['source'])==spec['source_sha256'],'Source pin');hashes[spec['source']]=spec['source_sha256'];}save('$raw/paired-identities.json',{'hashes':hashes,'planned_processes':112,'preparation':16,'measured':96,'variants':{'old':cli,'new':trialCli},'settings':'Auto workers; retained single-file8MiB cache and BulkImport Auto; affinity0-4; plaintext unsigned Zstd3 defaultpadding; four source/workflow cohorts; create/verify outside timed add'});}
void pairedIdentities(){for(final e in (object('$raw/paired-identities.json')['hashes'] as Map).entries)require(sha(e.key)==e.value,'Changed paired identity');}
void batch(){pairedIdentities();final output=File('$raw/paired-samples.jsonl');require(!output.existsSync(),'Existing batch');final started=<int>[];var accepted=0;try{final specs=cases();for(var c=0;c<2;c++){started.add(c);agent(c,start:true);final spec=specs[c];final env=environment(c);for(var workflow=0;workflow<2;workflow++){for(var r=0;r<14;r++){final order=(r+c+workflow).isEven?['old','new']:['new','old'];for(var position=0;position<2;position++){final variant=order[position];final executable=variant=='old'?cli:trialCli;final id='c$c-w$workflow-r$r-p$position-$variant';final archive='${spec['root']}/$id.lbox';final destination='${spec['root']}/$id.out';require(!File(destination).existsSync(),'Fresh output');budget(3*(spec['bytes'] as int)+256*1024*1024);create(archive,env,id);cold(spec['source'] as String,env,id);final timing='$raw/$id.time';run(['/usr/bin/time','-f','%e %U %S %M','-o',timing,'/usr/bin/taskset','-c','0-4',...addArgs(spec,archive,workflow,executable:executable)],env,id,maximum:600);final metrics=File(timing).readAsStringSync().trim().split(RegExp(r'\s+')).map(double.parse).toList();require(metrics.length==4&&metrics.every((v)=>v.isFinite&&v>=0)&&metrics[0]>0&&metrics[3]>0,'Metrics');run(['/usr/bin/sync','-d','--',archive,File(archive).parent.path],env,'$id-archive-drain',maximum:60);budget(spec['bytes'] as int);final path=verifyArchive(spec,archive,workflow,env,id);run([cli,archive,'extract',path,destination],env,'$id-extract',maximum:600);verifyOutput(spec,destination,env,id);final row={'case':spec['case'],'workflow':workflow==0?'single-file-interactive':'one-file-directory-bulkimport','variant':variant,'position':position,'round':r,'preparation':r<2,'elapsed_seconds':metrics[0],'user_seconds':metrics[1],'system_seconds':metrics[2],'rss_bytes':metrics[3]*1024,'archive_sha256':sha(archive),'archive_bytes':File(archive).lengthSync(),'source_sha256':spec['source_sha256'],'public_path':path,'persisted_bytes_mode_verified':true,'cold_source':true,'archive_and_output_drained_after_timing':true,'executable':executable};File(destination).deleteSync();File(archive).deleteSync();output.writeAsStringSync('${jsonEncode(row)}\n',mode:FileMode.append,flush:true);accepted++;}}}}}finally{cleanupAgents(started);}pairedIdentities();require(accepted==112,'Exact112');save('$raw/paired-complete.json',{'accepted':accepted,'measured':96,'preparation':16,'identities_verified_after':true,'owned_agents_stopped':true,'wall_seconds':wall.elapsedMilliseconds/1000});}
Future<void> main(List<String> args)async{require(Platform.isLinux&&args.length==1,'Linux setup|freeze|paired');final mask=DynamicLibrary.process().lookupFunction<Uint32 Function(Uint32),int Function(int)>('umask');final previous=mask(0x12);try{Directory(raw).createSync(recursive:true);counter=Directory('$raw/commands').existsSync()?Directory('$raw/commands').listSync().whereType<File>().length:0;switch(args.single){case 'setup':setup();print(green('Direct raw-body serialization source setup verified.'));break;case 'freeze':freeze();break;case 'paired':batch();break;default:throw ArgumentError('phase');}}finally{mask(previous);}}
